//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common_digital.js");
scwin.vBzProcsNo = "";
scwin.vIsuCd = "";
scwin.vIsuNm = "";
scwin.vIsurCd = "";
scwin.vProcsStatCd = "";
scwin.vListBzTpCd = "792"; // 상장원부 관리
scwin.gJobTitle = js_jobtitl; // 팀장  : 09,  부서장: 40,  팀원: 03

scwin.vScrenID = 'ULDSTF70032P.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; // 상장원부 검토승인 

scwin.fn_list_sync = function(vSrchIsuCd) {
    var url = "/digital/DigitalListinvstg.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listDigitalChangeDetailLog";
    url += "&ISU_CD=" + vSrchIsuCd;
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
};



/*********************************************************************** 
 * 함수명    : fn_sameYn()
 * 설명       : 일치여부 확인
 ***********************************************************************/
scwin.fn_sameYn = function(src1, src2) {
    if (src1 == "" && src2 == "") {
        return '-';
    } else if (src1 == src2) {
        return 'O';
    } else {
        return 'X';
    }
};



/********************************************** 
 * 함수명 : fn_parentRefresh()
 * 설명    : Parent 화면 Refresh()
 ***********************************************/
scwin.fn_parentRefresh = function() {
    //Parent 신청내역 화면 Refresh
    var parentWin = $c.frame.path("../");
    parentWin.fn_list_sync();
};



/*********************************************************************** 
 * 함수명    : fn_setItem()
 * 파라메터 : vIdx(순서), strNm(항목명), strCd(항목ID), dtsObj(데이터셋)
 * 설명       : 일반 데이터에 대해 Row 표시
 ***********************************************************************/
scwin.fn_setItem = function(vIdx, strNm, strCd, dtsObj) {
    dts_Log.setCellData(vIdx, 'ITEM', strNm);
    if (dtsObj != "") {
        dts_Log.setCellData(vIdx, 'VALUE1', dtsObj.getCellData(1, strCd));
        dts_Log.setCellData(vIdx, 'VALUE2', dtsObj.getCellData(2, strCd));
        dts_Log.setCellData(vIdx, 'CORRYN', scwin.fn_sameYn(dtsObj.getCellData(1, strCd), dtsObj.getCellData(2, strCd)));
    }
};



/*********************************************************************** 
 * 함수명    : fn_setItem_Date2()
 * 파라메터 : vIdx(순서), strNm(항목명), strCd1(항목ID1), strCd2(항목ID2), dtsObj(데이터셋)
 * 설명       : 날짜 데이터에 대해 포맷지정 후 Row 표시
 ***********************************************************************/
scwin.fn_setItem_Date2 = function(vIdx, strNm, strCd1, strCd2, dtsObj) {
    var date1 = "";
    var date2 = "";
    if (($c.stf.FormatDateEx(dtsObj.getCellData(1, strCd1)) != "") && ($c.stf.FormatDateEx(dtsObj.getCellData(1, strCd2)) != "")) {
        date1 = $c.stf.FormatDateEx(dtsObj.getCellData(1, strCd1)) + " ~ " + $c.stf.FormatDateEx(dtsObj.getCellData(1, strCd2));
    } else if ($c.stf.FormatDateEx(dtsObj.getCellData(1, strCd1)) != "") {
        date1 = $c.stf.FormatDateEx(dtsObj.getCellData(1, strCd1));
    } else {
        date1 = $c.stf.FormatDateEx(dtsObj.getCellData(1, strCd2));
    }
    if (($c.stf.FormatDateEx(dtsObj.getCellData(2, strCd1)) != "") && ($c.stf.FormatDateEx(dtsObj.getCellData(2, strCd2)) != "")) {
        date2 = $c.stf.FormatDateEx(dtsObj.getCellData(2, strCd1)) + " ~ " + $c.stf.FormatDateEx(dtsObj.getCellData(2, strCd2));
    } else if ($c.stf.FormatDateEx(dtsObj.getCellData(2, strCd1)) != "") {
        date2 = $c.stf.FormatDateEx(dtsObj.getCellData(2, strCd1));
    } else {
        date2 = $c.stf.FormatDateEx(dtsObj.getCellData(2, strCd2));
    }
    dts_Log.setCellData(vIdx, 'ITEM', strNm);
    dts_Log.setCellData(vIdx, 'VALUE1', date1);
    dts_Log.setCellData(vIdx, 'VALUE2', date2);
    dts_Log.setCellData(vIdx, 'CORRYN', scwin.fn_sameYn(date1, date2));
};


/*********************************************************************** 
 * 함수명    : fn_setItem_Number()
 * 파라메터 : vIdx(순서), strNm(항목명), strCd(항목ID), dtsObj(데이터셋)
 * 설명       : 숫자 데이터에 대해 포맷지정 후 Row 표시
 ***********************************************************************/
scwin.fn_setItem_Number = function(vIdx, strNm, strCd, dtsObj) {
    dts_Log.setCellData(vIdx, 'ITEM', strNm);
    var data1 = $c.stf.FormatNumberEx(dtsObj.getCellData(1, strCd));
    var data2 = $c.stf.FormatNumberEx(dtsObj.getCellData(2, strCd));
    dts_Log.setCellData(vIdx, 'VALUE1', data1);
    dts_Log.setCellData(vIdx, 'VALUE2', data2);
    dts_Log.setCellData(vIdx, 'CORRYN', scwin.fn_sameYn(dtsObj.getCellData(1, strCd), dtsObj.getCellData(2, strCd)));
};

/*********************************************************************** 
 * 함수명    : fn_setItem_yyyymm()
 * 파라메터 : vIdx(순서), strNm(항목명), strCd(항목ID), dtsObj(데이터셋)
 * 설명       : 일반 데이터에 대해 Row 표시
 ***********************************************************************/
scwin.fn_setItem_yyyymm = function(vIdx, strNm, strCd, dtsObj) {
    var ym1 = dtsObj.getCellData(1, strCd);
    var ym2 = dtsObj.getCellData(2, strCd);
    var data1 = "";
    var data2 = "";
    if (ym1.length == 6) {
        data1 = ym1.substring(0, 4) + "-" + ym1.substring(4, 6);
    } else {
        data1 = ym1;
    }
    if (ym2.length == 6) {
        data2 = ym2.substring(0, 4) + "-" + ym2.substring(4, 6);
    } else {
        data2 = ym2;
    }
    dts_Log.setCellData(vIdx, 'ITEM', strNm);
    dts_Log.setCellData(vIdx, 'VALUE1', data1);
    dts_Log.setCellData(vIdx, 'VALUE2', data2);
    dts_Log.setCellData(vIdx, 'CORRYN', scwin.fn_sameYn(ym1, ym2));
};

/*********************************************************************** 
 * 함수명    : fn_setItem_yymm()
 * 파라메터 : vIdx(순서), strNm(항목명), strCd(항목ID), dtsObj(데이터셋)
 * 설명       : 일반 데이터에 대해 Row 표시
 ***********************************************************************/
scwin.fn_setItem_yymm = function(vIdx, strNm, strCd, dtsObj) {
    var ym1 = dtsObj.getCellData(1, strCd);
    var ym2 = dtsObj.getCellData(2, strCd);
    var data1 = "";
    var data2 = "";
    if (ym1.length == 4) {
        data1 = ym1.substring(0, 2) + "-" + ym1.substring(2, 4);
    } else {
        data1 = ym1;
    }
    if (ym2.length == 4) {
        data2 = ym2.substring(0, 2) + "-" + ym2.substring(2, 4);
    } else {
        data2 = ym2;
    }
    dts_Log.setCellData(vIdx, 'ITEM', strNm);
    dts_Log.setCellData(vIdx, 'VALUE1', data1);
    dts_Log.setCellData(vIdx, 'VALUE2', data2);
    dts_Log.setCellData(vIdx, 'CORRYN', scwin.fn_sameYn(ym1, ym2));
};

/*********************************************************************** 
 * 함수명    : fn_setItem_Date()
 * 파라메터 : vIdx(순서), strNm(항목명), strCd(항목ID), dtsObj(데이터셋)
 * 설명       : 날짜 데이터에 대해 포맷지정 후 Row 표시
 ***********************************************************************/
scwin.fn_setItem_Date = function(vIdx, strNm, strCd, dtsObj) {
    dts_Log.setCellData(vIdx, 'ITEM', strNm);
    dts_Log.setCellData(vIdx, 'VALUE1', $c.stf.FormatDateEx(dtsObj.getCellData(1, strCd)));
    dts_Log.setCellData(vIdx, 'VALUE2', $c.stf.FormatDateEx(dtsObj.getCellData(2, strCd)));
    dts_Log.setCellData(vIdx, 'CORRYN', scwin.fn_sameYn(dtsObj.getCellData(1, strCd), dtsObj.getCellData(2, strCd)));
};
