//접수 또는 반려처리
scwin.fn_trs = function(listProcsStatCd) {
    vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
    scwin.vBzProcsNo = dts_List.getCellData(1, "BZ_PROCS_NO"); // 업무처리번호
    scwin.vIsuCd = dts_List.getCellData(1, "ISU_CD"); // 종목코드
    scwin.vIsurCd = dts_List.getCellData(1, "LIST_APPLNT_ISUR_CD"); // 상장인 발행기관 코드

    trs_Save.Action = "/digital/DigitalListinvstg.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcTpCd + "&method=updateDigitalChangAppl";
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_List)";
    trs_Save.Parameters = "TRS_IDX=" + TR_JOB_UPDATE + ",LD_MKT_TP_CD=1" + ",LIST_PROCS_STAT_CD=" + listProcsStatCd + ",LIST_BZ_TP_CD=" + scwin.vListBzTpCd + ",BZ_PROCS_NO=" + scwin.vBzProcsNo + ",ISU_CD=" + scwin.vIsuCd + ",ISUR_CD=" + scwin.vIsurCd + ",PROCS_EMP_NO=" + js_emp_no + ",ACPT_NO=" + js_emp_no + ",TRANSTR_EMP_NO=" + js_emp_no;
    trs_Save.Post();
};
scwin.btn_Close_onclick = async function() {
    //닫기(수량변경)
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    var parentWin = $c.frame.path("../");

    // 업무처리번호
    scwin.vBzProcsNo = parentWin.clickBzProcsNo;
    // 종목코드
    scwin.vIsuCd = parentWin.clickIsuCd;
    scwin.vIsuNm = parentWin.clickIsuNm;
    scwin.vProcsStatCd = parentWin.clickProcsStatCd;
    $c.stf.setObjectValue(txb_ISU_CD, scwin.vIsuCd);
    $c.stf.setObjectValue(txb_ISU_NM, scwin.vIsuNm);
    var vHeadString = "ITEM:STRING(100),VALUE1:STRING(300),VALUE2:STRING(300),CORRYN:STRING(1)";
    //dts_Log.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    scwin.fn_list_sync(scwin.vIsuCd);
    if (scwin.gJobTitle != "09") {
        // 팀장이 아닐경우
        $c.stf.showObj(btn_Revw, false);
        $c.stf.showObj(btn_Cls, false);
    } else {
        // 팀장일 경우 
        // 상태코드가 34(수정요청) 일 경우에만 승인/반려 가능
        if (scwin.vProcsStatCd != "34") {
            btn_Revw.src = "../img/btn_BosApv_d.gif";
            btn_Revw.setDisabled(true);
            btn_Cls.src = "../img/btn_BosReject_d.gif";
            btn_Cls.setDisabled(true);
        } else {
            btn_Revw.src = "../img/btn_BosApv.gif";
            btn_Revw.setDisabled(false);
            btn_Cls.src = "../img/btn_BosReject.gif";
            btn_Cls.setDisabled(false);
        }
    }
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    grd_List.Redraw = false;
    //일치항목 표시
    scwin.fn_setListingData();
    grd_List.redraw = true;
    dts_Log.setRowPosition(1, 0);
};
scwin.trs_Save_OnFail = function() {
    $c.lcd.fn_alertMsg('F');
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = async function() {
    $c.lcd.fn_alertMsg('S');
    //fn_getBaseInfo_read_sync();
    scwin.fn_parentRefresh();
    await $c.frame.CloseFrame();
};
scwin.btn_Cls_onclick = function() {
    var vAnswer = confirm('반려처리 하시겠습니까?');
    if (vAnswer == true) {
        LastJob = "반려";
        scwin.fn_trs("37");
    }
};
scwin.btn_Revw_onclick = function() {
    var vAnswer = confirm('승인처리 하시겠습니까?');
    if (vAnswer == true) {
        LastJob = "승인";
        scwin.fn_trs("35");
    }
};
